/**
 * frontend/src/components/Enrollment.jsx - ENRÔLEMENT ÉTUDIANT
 * ✅ Compatible avec api_service.js (FileReader)
 * ✅ Preview image
 * ✅ Validation stricte
 */

import React, { useState } from 'react';
import { studentsAPI } from '../api_service';

const COLORS = {
  primary: '#4F46E5',
  success: '#10B981',
  danger: '#EF4444',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  surface: '#FFFFFF'
};

const Enrollment = ({ addNotification }) => {
  const [formData, setFormData] = useState({ name: '', email: '' });
  const [file, setFile] = useState(null);
  const [preview, setPreview] = useState(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState(null);
  const [messageType, setMessageType] = useState('info');

  const showMessage = (msg, type = 'info') => {
    setMessage(String(msg));
    setMessageType(type);

    if (type === 'success' || type === 'error') {
      setTimeout(() => setMessage(null), 5000);
    }
  };

  const handleFileSelect = (e) => {
    const selectedFile = e.target.files?.[0];
    if (!selectedFile) return;

    if (!selectedFile.type.startsWith("image/")) {
      showMessage("❌ Veuillez sélectionner une image valide", "error");
      return;
    }

    setFile(selectedFile);

    const reader = new FileReader();
    reader.onload = (event) => {
      if (typeof event.target?.result === 'string') {
        setPreview(event.target.result);
      }
    };
    reader.readAsDataURL(selectedFile);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const name = formData.name.trim();
    const email = formData.email?.trim() || null;

    if (!name || !file) {
      showMessage("❌ Nom et image requis", "error");
      return;
    }

    setLoading(true);

    try {
      showMessage("⏳ Envoi en cours...", "info");

      const response = await studentsAPI.enrollFromImage(
        name,
        email,
        file
      );

      if (response.success) {
        showMessage(`✅ ${response.data.name} enrôlé avec succès !`, "success");
        addNotification(`✅ ${response.data.name} enrôlé`, 'success');

        setFormData({ name: '', email: '' });
        setFile(null);
        setPreview(null);
      } else {
        throw new Error(response.error || "Erreur inconnue");
      }

    } catch (err) {
      const errorMsg = err.message || "Erreur serveur";
      showMessage(`❌ ${errorMsg}`, "error");
      addNotification(`❌ ${errorMsg}`, 'error');
    }

    setLoading(false);
  };

  const messageColors = {
    success: { bg: '#DCFCE7', text: '#166534' },
    error: { bg: '#FEE2E2', text: '#991B1B' },
    info: { bg: '#DBEAFE', text: '#0C4A6E' }
  };

  const msgColor = messageColors[messageType];

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <h2 style={styles.title}>➕ Enrôler un étudiant</h2>

        {message && (
          <div style={{
            ...styles.message,
            backgroundColor: msgColor.bg,
            color: msgColor.text
          }}>
            {message}
          </div>
        )}

        <form onSubmit={handleSubmit} style={styles.form}>
          <input
            type="text"
            placeholder="Nom complet"
            value={formData.name}
            onChange={(e) =>
              setFormData({ ...formData, name: e.target.value })
            }
            style={styles.input}
            disabled={loading}
            required
          />

          <input
            type="email"
            placeholder="Email (optionnel)"
            value={formData.email}
            onChange={(e) =>
              setFormData({ ...formData, email: e.target.value })
            }
            style={styles.input}
            disabled={loading}
          />

          <input
            type="file"
            accept="image/*"
            onChange={handleFileSelect}
            disabled={loading}
            required
          />

          {preview && (
            <img
              src={preview}
              alt="preview"
              style={styles.preview}
            />
          )}

          <button
            type="submit"
            disabled={loading}
            style={{
              ...styles.button,
              opacity: loading ? 0.6 : 1,
              cursor: loading ? 'not-allowed' : 'pointer'
            }}
          >
            {loading ? "⏳ Traitement..." : "✅ Enrôler"}
          </button>
        </form>
      </div>
    </div>
  );
};

const styles = {
  container: {
    maxWidth: "500px",
    margin: "40px auto"
  },
  card: {
    padding: "30px",
    borderRadius: "15px",
    background: COLORS.surface,
    border: `1px solid ${COLORS.border}`,
    boxShadow: "0 2px 10px rgba(0,0,0,0.03)"
  },
  title: {
    textAlign: "center",
    marginBottom: "25px",
    color: COLORS.textMain
  },
  form: {
    display: "flex",
    flexDirection: "column",
    gap: "15px"
  },
  input: {
    padding: "12px",
    borderRadius: "8px",
    border: `1px solid ${COLORS.border}`,
    fontSize: "14px",
    fontFamily: "inherit",
    outline: "none",
    transition: "border-color 0.2s"
  },
  preview: {
    width: "100%",
    borderRadius: "10px",
    marginTop: "10px"
  },
  button: {
    padding: "12px",
    borderRadius: "10px",
    background: COLORS.primary,
    color: "white",
    border: "none",
    cursor: "pointer",
    fontWeight: "600",
    marginTop: "10px"
  },
  message: {
    padding: "12px",
    borderRadius: "8px",
    marginBottom: "15px",
    fontSize: "0.9rem"
  }
};

export default Enrollment;
